cd /home/exedev/shipshape-shakedown/.eval-scratch/F6-midway-hy3/sim && node -e '
const fs=require("fs");
const wb=JSON.parse(fs.readFileSync("watchbill.json","utf8"));
const names=new Set();
for(const f of fs.readdirSync("features").filter(f=>f.endsWith(".feature")))
  for(const l of fs.readFileSync("features/"+f,"utf8").split("\n"))
    { const m=l.match(/^\s*Scenario:\s*(.+?)\s*$/); if(m) names.add("features/"+f+":"+m[1]); }
let n=0,bad=[];
for(const w of Object.keys(wb)) for(const s of wb[w].scenarios){n++; if(!names.has(s)) bad.push(s);}
console.log("scenarios in specs:",names.size,"watchbill refs:",n,"unmatched:",bad.length,bad);
const listed=new Set(Object.values(wb).flatMap(w=>w.scenarios));
console.log("specs not in watchbill:",[...names].filter(x=>!listed.has(x)));
'
